import click
from click.testing import CliRunner

def test_fish_completion_multiline_help():
    @click.command()
    @click.option(
        "--opt",
        help="Line 1\\nLine 2",
    )
    def cli(opt):
        pass

    runner = CliRunner()
    result = runner.invoke(
        cli,
        [],
        env={
            "_CLICK_COMPLETE": "fish_source",
        },
    )

    assert result.exit_code == 0
    expected_problematic_line = "plain,--opt\\nLine 1\\nLine 2"
    assert expected_problematic_line not in result.output
